 z=dict(passed=True,closed=True,scope='MANUSCRIPT_EVIDENCE_UPDATE_ONLY',local_time=datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=8))).isoformat(),canonical_common_records_SHA_verified=72,common_totals=d['totals'],input_SHA256={str(p.relative_to(R)):sha(p)for p in inputs},manuscript_before_sha256=old_sha,manuscript_after_sha256=sha(P),models=0,optimizer_calls=0,physics=0,replay=0,new_physical_audits=0,new_formal_claims=0,old_snapshot_unchanged=True,source_sha256=sha(Path(__file__)),late_after_prior_releases=True);(S/'PROVENANCE.json').write_text(json.dumps(z,indent=2)+'\n');print(json.dumps(z))
